const $=s=>document.querySelector(s);let files=[],urls=[],example=false,detectedDocument=null,draftTargetLanguage=null;let toastTimer;const typeNames={license:'Führerschein',birth:'Geburtsurkunde',marriage:'Heiratsurkunde',other:'Urkunde'};
function toast(message){(document.querySelector('dialog[open]')||document.body).append($('#toast'));$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function view(name){$('#studio-intro').hidden=name!=='studio';for(const n of ['studio','documents','guide','review','workspace']){$(`#${n}-view`).hidden=n!==name;document.querySelector(`[data-view="${n}"]`)?.classList.toggle('active',n===name)}$('#breadcrumb').textContent={studio:'Übersetzen',documents:'Bibliothek',guide:'Hinweise',review:'Bearbeiten',workspace:'Anlernen'}[name];const reviewExtras=$('#review-extras');if(reviewExtras)reviewExtras.hidden=name!=='review';if(name==='documents')renderDocuments();if(name==='workspace'&&typeof loadLibrary==='function')void loadLibrary();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));for(const id of ['help','workflow-help','sources']){const button=$(`#${id}`);if(button)button.onclick=()=>view('guide');}
$('#pick').onclick=e=>{e.stopPropagation();$('#file').click()};$('#dropzone').onclick=()=>$('#file').click();$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file').click()}};$('#file').onchange=e=>{addFiles(e.target.files);e.target.value=''};
for(const type of ['dragenter','dragover'])$('#dropzone').addEventListener(type,e=>{e.preventDefault();$('#dropzone').classList.add('dragover')});for(const type of ['dragleave','drop'])$('#dropzone').addEventListener(type,e=>{e.preventDefault();$('#dropzone').classList.remove('dragover');if(type==='drop')addFiles(e.dataTransfer.files)});
function resetPreview(){urls.forEach(URL.revokeObjectURL);urls=[];$('#preview').replaceChildren()}
function invalidateDraft(){if(typeof cachedPDF!=='undefined')cachedPDF=null;if(typeof cachedWord!=='undefined')cachedWord=null;example=false;detectedDocument=null;draftTargetLanguage=null;if(typeof convertedPreviews!=='undefined')convertedPreviews.clear();$('#translation').value='';$('#editor').hidden=true;document.querySelectorAll('.review-checks input').forEach(i=>i.checked=false);document.querySelectorAll('.step').forEach(s=>s.classList.toggle('active',s.dataset.step==='1'))}
const fileRoles=new WeakMap(),fileHashes=new WeakMap();let intakeTail=Promise.resolve();
function addFiles(incoming){const captured=[...incoming];intakeTail=intakeTail.then(()=>addUniqueFiles(captured)).catch(e=>{ $('#error').textContent=e.message;});}
async function addUniqueFiles(incoming){if(typeof translating!=='undefined' && translating)return;let errors=[],accepted=[];for(const f of incoming){if(!/\.(pdf|docx|doc|odt|rtf|txt|md|jpe?g|png|webp|gif|tiff?|bmp|heic|heif|avif)$/i.test(f.name)){errors.push(`${f.name}: Dateiformat nicht unterstützt.`);continue}if(!f.size||f.size>20*1024*1024){errors.push(`${f.name}: Datei leer oder größer als 20 MB.`);continue}if(files.length+accepted.length>=10){errors.push('Maximal 10 Dateien pro Sitzung.');break}const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');if([...files,...accepted].some(x=>fileHashes.get(x)===hash)){errors.push(f.name+': identischer Inhalt bereits ausgewählt.');continue;}fileHashes.set(f,hash);accepted.push(f)}if(accepted.length){invalidateDraft();files.push(...accepted);renderFiles()}$('#error').textContent=errors.join(' ')}
function makeRow(f,i){const row=document.createElement('div');row.className='file-item';const icon=document.createElement('b');icon.textContent=f.name.split('.').pop().toUpperCase().slice(0,5);const name=document.createElement('span');name.textContent=f.name;const size=document.createElement('small');size.textContent=`Datei ${i+1} · ${(f.size/1024/1024).toFixed(2)} MB · lokal ausgewählt`;name.append(size);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`${f.name} entfernen`);remove.onclick=()=>{files.splice(i,1);invalidateDraft();resetPreview();renderFiles();renderDocuments()};const order=document.createElement('div');order.className='file-order';for(const [symbol,delta,label] of [['↑',-1,'nach oben'],['↓',1,'nach unten']]){const button=document.createElement('button');button.textContent=symbol;button.disabled=i+delta<0||i+delta>=files.length;button.setAttribute('aria-label',`${f.name} ${label}`);button.onclick=()=>{[files[i],files[i+delta]]=[files[i+delta],files[i]];invalidateDraft();resetPreview();renderFiles();renderDocuments();};order.append(button);}const role=document.createElement('select');role.className='file-role';role.setAttribute('aria-label',f.name+' Seitenrolle');for(const [value,label]of [['auto','Automatisch'],['front','Vorderseite'],['back','Rückseite'],['attachment','Beilage']])role.add(new Option(label,value));role.value=fileRoles.get(f)||'auto';role.onchange=()=>{fileRoles.set(f,role.value);invalidateDraft();};row.append(icon,name,role,order,remove);return row}
function renderFiles(){$('#file-list').replaceChildren(...files.map(makeRow));$('#doc-count').textContent=files.length;$('#dropzone h3').textContent=files.length?'Weitere Seite hinzufügen':'Datei hier ablegen'}
function renderDocuments(){const target=$('#document-cards');target.replaceChildren();if(typeof queueState!=='undefined'){const groups=new Map();for(const job of queueState.jobs||[]){const detected=job.detected?.documentType||'Dokumenttyp noch nicht erkannt',key=/führerschein|driving licence/i.test(detected)?'Führerscheine':/geburtsurkunde|birth certificate/i.test(detected)?'Geburtsurkunden':/(?:^|\s)pass(?:\s|$)|passport/i.test(detected)?'Pässe':detected;groups.set(key,[...(groups.get(key)||[]),job]);}for(const [name,jobs]of groups){const folder=document.createElement('section');folder.className='library-folder';const heading=document.createElement('h2');heading.textContent=name;const count=document.createElement('span');count.className='tag';count.textContent=String(jobs.length);heading.append(count);folder.append(heading);for(const job of jobs){const row=document.createElement('div');row.className='library-job';const title=document.createElement('strong');title.textContent=job.names.join(' · ');const status=document.createElement('small');status.textContent=job.status==='succeeded'?'Übersetzung fertig':job.status==='failed'?'Fehlgeschlagen':job.status==='awaiting_answers'?'Rückfrage offen':'In Bearbeitung';row.append(title,status);if(job.hasResult){const actions=document.createElement('div');actions.className='library-job-actions';for(const [label,action]of [['PDF ↓','download'],['Word ↓','word'],['Öffnen','review']]){const button=document.createElement('button');button.className='text-button';button.textContent=label;button.onclick=()=>queueAction(action,job);actions.append(button);}row.append(actions);}folder.append(row);}target.append(folder);}}if(!target.childElementCount){const p=document.createElement('p');p.textContent='Noch keine Aufträge vorhanden. Lade dein erstes Dokument im Übersetzungsstudio hoch.';target.append(p)}if(files.length){const heading=document.createElement('h2');heading.textContent='Aktuelle Dateiauswahl';target.append(heading,...files.map((f,i)=>makeRow(f,i)));}const b=document.createElement('button');b.className='primary';b.style.marginTop='20px';b.textContent='Zurück zum Übersetzen →';b.onclick=()=>view('studio');target.append(b)}
function openEditor(){if(!files.length&&!example){$('#error').textContent='Bitte zuerst eine Datei auswählen oder das Beispieldokument öffnen.';$('#dropzone').focus();return}$('#error').textContent='';$('#editor').hidden=false;$('#draft-title').textContent=detectedDocument?`${detectedDocument.documentType} · ${detectedDocument.sourceLanguage} → ${draftTargetLanguage||$('#target-language').value}`:`Automatisch erkennen → ${$('#target-language').value}`;$('#draft-tag').textContent=example?'Fiktive Beispieldaten':'Manueller Entwurf';$('#source-label').textContent=example?'Fiktives Beispiel':'Lokale Datei';resetPreview();if(example){const box=document.createElement('div');box.style.cssText='background:#f5f5f5;border:1px solid #d4d4d4;padding:28px 20px;line-height:2;text-align:center;width:100%;color:#555555';const h=document.createElement('h3');h.textContent='FIKTIVES MUSTER';const ar=document.createElement('p');ar.lang='ar';ar.dir='rtl';ar.textContent='جمهورية مصر العربية\nوزارة الداخلية\nرخصة قيادة\nالاسم: أحمد محمد حسن';ar.style.cssText='white-space:pre-line;font-size:19px;color:#292929;margin:24px 0';const p=document.createElement('p');p.textContent='Nur zur Demonstration der Oberfläche. Kein echtes Ausweisdokument.';box.append(h,ar,p);$('#preview').append(box)}else{const selector=document.createElement('select');selector.setAttribute('aria-label','Datei für Originalvorschau auswählen');files.forEach((f,i)=>selector.add(new Option(f.name,i)));const frame=document.createElement('div');frame.style.width='100%';function display(){frame.replaceChildren();urls.forEach(URL.revokeObjectURL);urls=[];const f=files[+selector.value];if(typeof renderFilePreview==='function'){renderFilePreview(f,frame);return;}const p=document.createElement('p');p.textContent='Originaldatei ausgewählt.';frame.append(p)}selector.onchange=display;$('#preview').append(selector,frame);display()}document.querySelectorAll('.step').forEach(s=>s.classList.toggle('active',Number(s.dataset.step)<=2));$('#editor').scrollIntoView({behavior:'smooth',block:'start'})}
$('#continue').onclick=openEditor;$('#target-language').onchange=()=>{if(cachedPDF)cachedPDF=null;if(!$('#editor').hidden){$('#draft-tag').textContent='Zielsprache geändert · erneut übersetzen';}};
