$('#clear-files').onclick=()=>{files=[];invalidateDraft();resetPreview();renderFiles();$('#file').value='';toast('Dateien und Entwurf aus dieser Sitzung entfernt.')};
function outputTitle(){const source=detectedDocument?.sourceLanguage,from={Arabisch:'dem Arabischen',Englisch:'dem Englischen',Deutsch:'dem Deutschen',Französisch:'dem Französischen',Türkisch:'dem Türkischen'}[source],target=draftTargetLanguage||$('#target-language').value,to={Deutsch:'ins Deutsche',Englisch:'ins Englische',Arabisch:'ins Arabische',Französisch:'ins Französische',Spanisch:'ins Spanische',Italienisch:'ins Italienische',Türkisch:'ins Türkische'}[target];return `Beglaubigte Übersetzung ${from?'aus '+from:'von '+(source||'der Ausgangssprache')} ${to||'nach '+target}`;}
function exportText(){const text=$('#translation').value.trim();if(!text){toast('Bitte zuerst eine Übersetzung eingeben.');return null}if(/zu prüfen|prüfhinweis|\b(?:TODO|TBD)\b/i.test(text)){toast('Bitte offene Angaben vor dem Export klären.');return null}return `${outputTitle()}\n\n${text}`}
function exported(){document.querySelectorAll('.step').forEach(s=>s.classList.add('active'));toast('Übersetzung exportiert.')}
$('#download').onclick=()=>{const text=exportText();if(!text)return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='translateocr-uebersetzung.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exported()};$('#print').onclick=()=>{const text=exportText();if(!text)return;$('#print-area').replaceChildren();const h=document.createElement('h1');h.textContent=outputTitle();const p=document.createElement('div');p.textContent=$('#translation').value.trim();$('#print-area').append(h,p);window.print();exported()};window.addEventListener('beforeunload',()=>urls.forEach(URL.revokeObjectURL));
